-- KAIN PANJANG (id_jenis = 1)
(1, 1, 'Kain Iwak Etong Royal Blue', 'https://i.pinimg.com/1200x/1d/c7/6b/1dc76be61a727fc26275e2070a43a0a5.jpg', 1850000, 15, '250 × 110 cm', 'Katun Primissima', 'Tulis Complongan', 'Kain panjang bermotif ikan etong khas laut Jawa Utara. Melambangkan kelimpahan rezeki bahari dan rasa syukur nelayan Dermayon. Dikerjakan dengan teknik complongan selama 40 hari.'),
(2, 1, 'Kain Kapal Kandas Klasik', 'https://i.pinimg.com/1200x/80/62/51/8062513ccda78d5b48f1285043239676.jpg', 2100000, 15, '250 × 110 cm', 'Katun Primissima', 'Tulis Halus', 'Menceritakan kapal dagang kuno yang bersandar di muara Cimanuk. Simbol keteguhan hati dan pantang menyerah mengarungi samudra kehidupan.'),
(3, 1, 'Kain Merak Ngibing Premium', 'https://i.pinimg.com/1200x/8f/84/22/8f8422814f4175cf1907a40516b1abe7.jpg', 2750000, 15, '250 × 110 cm', 'Sutra ATBM', 'Tulis Sutra', 'Visualisasi tarian merak dengan sayap mengembang penuh keanggunan. Dibuat di atas sutra halus ATBM dengan pewarnaan alami dari daun mangga dan kayu mahoni.'),
(4, 1, 'Kain Sawat Kembang Pesisir', 'https://i.pinimg.com/736x/9f/ff/79/9fff79bc00baa77371567b9d3a36de12.jpg', 1650000, 15, '250 × 110 cm', 'Katun Primissima', 'Tulis Complongan', 'Motif bunga sawat yang mekar di tepi pantai Pantura. Menggambarkan keindahan alam pesisir Indramayu dan kesuburan tanah Dermayon.'),
(5, 1, 'Kain Mega Mendung Dermayon', 'https://i.pinimg.com/736x/ed/1b/c9/ed1bc9abe706ba2058fcf4b51df68761.jpg', 1950000, 15, '250 × 110 cm', 'Katun Primissima', 'Tulis Cap', 'Adaptasi motif mega mendung versi pesisir Dermayon dengan gradasi biru laut yang khas dan sentuhan rintik complongan.'),
(6, 1, 'Kain Udang Windu Bahari', 'https://i.pinimg.com/1200x/7b/7d/a7/7b7da76e1d305f43cf9ddda3e83f8bc3.jpg', 1750000, 15, '250 × 110 cm', 'Katun Prima', 'Tulis Halus', 'Motif udang windu melambangkan kemakmuran nelayan tambak di pesisir Indramayu. Dikerjakan dengan ketelitian tinggi oleh empu pembatik Paoman.'),
(8, 1, 'Kain Singa Barong Paoman', 'https://i.pinimg.com/1200x/40/9f/af/409fafab21f085588a2c6cb3c254c245.jpg', 3200000, 15, '250 × 110 cm', 'Sutra ATBM', 'Tulis Halus', 'Motif singa barong yang gagah melambangkan keberanian dan kekuatan. Masterpiece dari sentra Paoman dengan pewarnaan alami eksklusif.'),
(9, 1, 'Kain Buketan Flora Laut', 'https://i.pinimg.com/736x/b4/de/f8/b4def8983ecfe86d12ca4a4d5f2be8dc.jpg', 1550000, 15, '250 × 110 cm', 'Katun Prima', 'Tulis Cap', 'Rangkaian bunga dan flora laut yang disusun indah. Perpaduan warna biru pesisir dan hijau daun mangrove yang menyejukkan mata.'),
(11, 1, 'Kain Lokcan Burung Phoenix', 'https://i.pinimg.com/1200x/95/3d/de/953ddeb8fe354ddc006ed6cfa05e3367.jpg', 2850000, 15, '250 × 110 cm', 'Sutra Halus', 'Tulis Halus', 'Motif burung phoenix atau lokcan yang melambangkan kebangkitan dan kemakmuran. Dipengaruhi oleh budaya Tionghoa pesisir utara Jawa.'),
(10, 1, 'Kain Ganggeng Rumput Laut', 'https://i.pinimg.com/736x/39/2b/39/392b39f3a3af88a805254025c5c18b6b.jpg', 1450000, 15, '250 × 110 cm', 'Katun Prima', 'Cap Complongan', 'Motif rumput laut atau ganggeng yang bergoyang di dasar laut. Melambangkan kelenturan dan ketahanan hidup masyarakat pesisir.'),

